"C:\\windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$projectPath = '"'D:\\myWork\\github\\optimization-with-real-trajectory\\taowen\\saved_configs\\CampusNetwork_04'
"'$checks = @(
  @{Node='"'Core_SW_01'; Ifaces=@('GE1/0/3','GE1/0/8','GE1/0/9')},
  @{Node='Core_SW_02'; Ifaces=@('GE1/0/3','GE1/0/8','GE1/0/9')},
  @{Node='FW_01'; Ifaces=@('GigabitEthernet1/0/1','GigabitEthernet1/0/2','GigabitEthernet1/0/3')},
  @{Node='FW_02'; Ifaces=@('GigabitEthernet1/0/1','GigabitEthernet1/0/2','GigabitEthernet1/0/3')},
  @{Node='ChinaUnicom_SW'; Ifaces=@('GE1/0/1','GE1/0/4')}
)
foreach ("'$check in $checks) {
  $content = Get-Content -LiteralPath (Join-Path $projectPath "$($check.Node)'"\\display_interface.txt\") -Raw
  foreach ("'$iface in $check.Ifaces) {
    $pattern = '"'(?ms)"'^'"' + [regex]::Escape("'$iface) + '"' current state.*?(?="'^'"\\S+ current state|\\z)'
    "'$match = [regex]::Match($content,$pattern)
    "NODE=$($check.Node) INTERFACE=$iface"
    if ($match.Success) { $match.Value } else { '"'NO_MATCH' }
  }
}"

